import java.io.*;

public class Main {
    static long[] emptyCells(long n, long[] r, long[] c) {
        // Write your solution here
        return new long[0];
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        long n = (long) in.nval;
        in.nextToken();
        int k = (int) in.nval;
        long[] r = new long[k], c = new long[k];
        for (int i = 0; i < k; i++) {
            in.nextToken(); r[i] = (long) in.nval;
            in.nextToken(); c[i] = (long) in.nval;
        }
        long[] res = emptyCells(n, r, c);
        StringBuilder sb = new StringBuilder();
        for (long x : res) sb.append(x).append('\n');
        System.out.print(sb);
    }
}
